// Exact native geometry readout. No drawing save, approximation or design inference.
using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Security.Cryptography;using System.Web.Script.Serialization;
using Autodesk.AutoCAD.Runtime;using Autodesk.AutoCAD.DatabaseServices;using Autodesk.AutoCAD.Geometry;using App=Autodesk.AutoCAD.ApplicationServices.Core.Application;
public class NativeGeometryReadV1 {
 public class Source{public string path,sha256;public string[] handles;}
 public class Config{public Source[] sources;public string receipt;public bool self_test;}
 static readonly JavaScriptSerializer J=new JavaScriptSerializer{MaxJsonLength=100000000,RecursionLimit=100};
 static double[] P(Point2d p){return new[]{p.X,p.Y};}static double[] P(Point3d p){return new[]{p.X,p.Y,p.Z};}static double[] V(Vector2d p){return new[]{p.X,p.Y};}static double[] V(Vector3d p){return new[]{p.X,p.Y,p.Z};}
 static void Need(bool v,string m){if(!v)throw new InvalidOperationException(m);}
 public static string Hash(string p){using(var h=SHA256.Create())using(var f=File.Open(p,FileMode.Open,FileAccess.Read,FileShare.ReadWrite))return BitConverter.ToString(h.ComputeHash(f)).Replace("-","").ToLowerInvariant();}
 public static object Edge(Curve2d c){
  var l=c as LineSegment2d;if(l!=null)return new{kind="LINE2D",start=P(l.StartPoint),end=P(l.EndPoint)};
  var a=c as CircularArc2d;if(a!=null)return new{kind="ARC2D",center=P(a.Center),radius=a.Radius,reference_vector=V(a.ReferenceVector),start_angle=a.StartAngle,end_angle=a.EndAngle,clockwise=a.IsClockWise,start=P(a.StartPoint),end=P(a.EndPoint)};
  var e=c as EllipticalArc2d;if(e!=null)return new{kind="ELLIPSE2D",center=P(e.Center),major_axis=V(e.MajorAxis),minor_axis=V(e.MinorAxis),major_radius=e.MajorRadius,minor_radius=e.MinorRadius,start_angle=e.StartAngle,end_angle=e.EndAngle,clockwise=e.IsClockWise,start=P(e.StartPoint),end=P(e.EndPoint)};
  var n=c as NurbCurve2d;if(n!=null){var d=n.DefinitionData;return new{kind="NURBS2D",degree=d.Degree,rational=d.Rational,periodic=d.Periodic,control_points=d.ControlPoints.Cast<Point2d>().Select(P).ToArray(),knots=d.Knots.Cast<double>().ToArray(),weights=d.Weights.Cast<double>().ToArray()};}
  throw new NotSupportedException("EXACT_CURVE_NOT_SUPPORTED:"+c.GetType().Name);
 }
 public static object Geometry(Entity entity,bool includeDerivedArea=true){
  var text=entity as DBText;if(text!=null){
   object style=null;if(text.Database!=null&&!text.TextStyleId.IsNull)using(var tr=text.Database.TransactionManager.StartOpenCloseTransaction()){var st=(TextStyleTableRecord)tr.GetObject(text.TextStyleId,OpenMode.ForRead);style=new{handle=st.Handle.ToString(),name=st.Name,font_file=st.FileName,big_font_file=st.BigFontFileName};}
   return new{kind="DBTEXT",text=text.TextString,justify=text.Justify.ToString(),alignment_point=P(text.AlignmentPoint),horizontal_mode=text.HorizontalMode.ToString(),vertical_mode=text.VerticalMode.ToString(),position=P(text.Position),height=text.Height,width_factor=text.WidthFactor,rotation=text.Rotation,text_style=style,normal=V(text.Normal)};
  }
  var h=entity as Hatch;if(h!=null){var loops=new List<object>();for(int i=0;i<h.NumberOfLoops;i++){var loop=h.GetLoopAt(i);if(loop.IsPolyline)loops.Add(new{index=i,type=(int)loop.LoopType,type_name=loop.LoopType.ToString(),kind="BULGED_POLYLINE2D",vertices=loop.Polyline.Cast<BulgeVertex>().Select(v=>new{point=P(v.Vertex),bulge=v.Bulge}).ToArray()});else loops.Add(new{index=i,type=(int)loop.LoopType,type_name=loop.LoopType.ToString(),kind="CURVE_EDGES2D",edges=loop.Curves.Cast<Curve2d>().Select(Edge).ToArray()});}
   double? area=null;string area_error=null;if(includeDerivedArea)try{area=h.Area;}catch(System.Exception ex){area_error=ex.Message;}
   var definitions=Enumerable.Range(0,h.NumberOfPatternDefinitions).Select(i=>{var d=h.GetPatternDefinitionAt(i);return new{index=i,angle=d.Angle,base_point=new[]{d.BaseX,d.BaseY},offset=new[]{d.OffsetX,d.OffsetY},dashes=d.GetDashes().Cast<double>().ToArray()};}).ToArray();
   return new{kind="HATCH",coordinates="OCS; transform using normal and elevation",normal=V(h.Normal),elevation=h.Elevation,style=h.HatchStyle.ToString(),pattern=h.PatternName,pattern_type=h.PatternType.ToString(),pattern_scale=h.PatternScale,pattern_angle=h.PatternAngle,pattern_double=h.PatternDouble,origin=P(h.Origin),pattern_lines=definitions,associative=h.Associative,area,area_error,loops};}
  var p=entity as Polyline;if(p!=null)return new{kind="POLYLINE",normal=V(p.Normal),elevation=p.Elevation,closed=p.Closed,vertices=Enumerable.Range(0,p.NumberOfVertices).Select(i=>new{ocs=P(p.GetPoint2dAt(i)),wcs=P(p.GetPoint3dAt(i)),bulge=p.GetBulgeAt(i),start_width=p.GetStartWidthAt(i),end_width=p.GetEndWidthAt(i)}).ToArray()};
  var line=entity as Line;if(line!=null)return new{kind="LINE",start=P(line.StartPoint),end=P(line.EndPoint),normal=V(line.Normal),thickness=line.Thickness};
  var arc=entity as Arc;if(arc!=null)return new{kind="ARC",center=P(arc.Center),normal=V(arc.Normal),radius=arc.Radius,start_angle=arc.StartAngle,end_angle=arc.EndAngle,start=P(arc.StartPoint),end=P(arc.EndPoint),thickness=arc.Thickness};
  var circle=entity as Circle;if(circle!=null)return new{kind="CIRCLE",center=P(circle.Center),normal=V(circle.Normal),radius=circle.Radius,thickness=circle.Thickness};
  var ellipse=entity as Ellipse;if(ellipse!=null)return new{kind="ELLIPSE",center=P(ellipse.Center),normal=V(ellipse.Normal),major_axis=V(ellipse.MajorAxis),minor_axis=V(ellipse.MinorAxis),radius_ratio=ellipse.RadiusRatio,start_parameter=ellipse.StartParam,end_parameter=ellipse.EndParam};
  var spline=entity as Spline;if(spline!=null)using(var curve=spline.GetGeCurve()){var n=curve as NurbCurve3d;Need(n!=null,"NURBS3D_REQUIRED");var d=n.DefinitionData;return new{kind="NURBS3D",degree=d.Degree,rational=d.Rational,periodic=d.Periodic,control_points=d.ControlPoints.Cast<Point3d>().Select(P).ToArray(),knots=d.Knots.Cast<double>().ToArray(),weights=d.Weights.Cast<double>().ToArray()};}
  throw new NotSupportedException("EXACT_ENTITY_NOT_SUPPORTED:"+entity.GetRXClass().Name);
 }
 static object SelfTest(){using(var arc=new CircularArc2d(new Point2d(2,3),4,0,Math.PI,Vector2d.XAxis,false))using(var line=new LineSegment2d(new Point2d(0,0),new Point2d(2,2)))using(var spline=new NurbCurve2d(line)){
  var a=J.Serialize(Edge(arc));var b=J.Serialize(Edge(spline));Need(a.Contains("ARC2D")&&a.Contains("radius")&&b.Contains("NURBS2D")&&b.Contains("knots"),"NATIVE_CURVE_SELF_TEST");return new{status="PASSED",tests=new[]{"native circular arc parameters retained","native spline control points weights knots retained"}};}}
 [CommandMethod("HLCADGEOMETRYREADV1",CommandFlags.Session)] public void Run(){var ed=App.DocumentManager.MdiActiveDocument.Editor;var answer=ed.GetString(new Autodesk.AutoCAD.EditorInput.PromptStringOptions("\nGeometry request: "){AllowSpaces=true});if(answer.Status!=Autodesk.AutoCAD.EditorInput.PromptStatus.OK)return;Config c=null;var previous=HostApplicationServices.WorkingDatabase;try{
  c=J.Deserialize<Config>(File.ReadAllText(answer.StringResult.Trim('"')));Need(c.sources!=null&&c.sources.Length>0&&!File.Exists(c.receipt),"REQUEST_OR_OUTPUT_INVALID");var rows=new List<object>();bool complete=true;var tests=c.self_test?SelfTest():null;
  foreach(var source in c.sources){Need(Hash(source.path)==source.sha256,"SOURCE_HASH_CHANGED");Need(source.handles!=null&&source.handles.Length>0&&source.handles.Distinct(StringComparer.OrdinalIgnoreCase).Count()==source.handles.Length,"HANDLES_REQUIRED");using(var db=new Database(false,true)){db.ReadDwgFile(source.path,FileOpenMode.OpenForReadAndAllShare,true,null);db.CloseInput(true);HostApplicationServices.WorkingDatabase=db;using(var tr=db.TransactionManager.StartTransaction())foreach(var handle in source.handles){try{var entity=(Entity)tr.GetObject(db.GetObjectId(false,new Handle(Convert.ToInt64(handle,16)),0),OpenMode.ForRead);rows.Add(new{source=source.path,source_sha256=source.sha256,handle,type=entity.GetRXClass().Name,layer=entity.Layer,color=entity.ColorIndex,linetype=entity.Linetype,linetype_scale=entity.LinetypeScale,status="EXACT",geometry=Geometry(entity)});}catch(System.Exception ex){complete=false;rows.Add(new{source=source.path,source_sha256=source.sha256,handle,status="UNAVAILABLE",error=ex.ToString()});}}HostApplicationServices.WorkingDatabase=previous;}Need(Hash(source.path)==source.sha256,"READ_CHANGED_SOURCE");}
  using(var f=new FileStream(c.receipt,FileMode.CreateNew,FileAccess.Write))using(var w=new StreamWriter(f,new System.Text.UTF8Encoding(false)))w.Write(J.Serialize(new{status=complete?"EXACT_NATIVE_GEOMETRY_READ":"PARTIAL_NATIVE_GEOMETRY_READ",read_only=true,approximation=false,tests,rows}));
 }catch(System.Exception ex){if(c!=null&&!File.Exists(c.receipt))File.WriteAllText(c.receipt,J.Serialize(new{status="READ_FAILED",error=ex.ToString()}));}finally{HostApplicationServices.WorkingDatabase=previous;}}
}
